"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[555],{597:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-02-erm-least-squares</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-2-эмпирический-риск-и-метод-наименьших-квадратов">Лабораторная\nработа 2. Эмпирический риск и метод наименьших квадратов</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 1</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 1: функция потерь (опр. 1.9), эмпирический и истинный риск\n(опр. 1.10–1.11), утв. 1.12 о несмещённости, принцип ERM (опр. 1.13),\nсвязь ERM и ММП (утв. 1.15), матричное дифференцирование (§6),\nнормальные уравнения МНК (теорема 1.20)</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–4) + 4 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Превратить формулы лекции 1 в работающий код и проверить их численно:\nубедиться, что эмпирический риск несмещённо оценивает истинный\n<strong>только</strong> для алгоритма, выбранного независимо от выборки;\nпроверить формулы матричного дифференцирования конечными разностями;\nреализовать МНК двумя способами и увидеть, где нормальные уравнения\nчисленно проигрывают SVD; убедиться на эксперименте, что оценка\nмаксимального правдоподобия при гауссовском шуме совпадает с решением\nМНК.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab02_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<p>Вся работа — это проверка утверждений лекции 1 вычислительным\nэкспериментом. Формулы даны, доказательства прочитаны; здесь мы отвечаем\nна вопрос «а действительно ли так?» и заодно нарабатываем инструменты\nдля работ 3–9.</p>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-функция-потерь-и-эмпирический-риск">Часть 1. Функция\nпотерь и эмпирический риск</h1>\n<p>По определению 1.9, функция потерь\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>≥</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\mathcal L(a, x, y) \\ge 0</annotation></semantics></math>\nизмеряет ошибку алгоритма\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>a</mi><annotation encoding="application/x-tex">a</annotation></semantics></math>\nна объекте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>x</mi><annotation encoding="application/x-tex">x</annotation></semantics></math>\nс ответом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>;\nв регрессии она зависит только от невязки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>=</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi></mrow><annotation encoding="application/x-tex">r = a(x) - y</annotation></semantics></math>.\nЭмпирический риск (опр. 1.10):</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nQ(a, X^\\ell) \\;=\\; \\frac1\\ell \\sum_{i=1}^{\\ell} \\mathcal L(a, x_i, y_i).\n</annotation></semantics></math></p>\n<p>Реализуем четыре потери:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>ℒ</mi><mrow><mi mathvariant="normal">s</mi><mi mathvariant="normal">q</mi></mrow></msub><mo stretchy="false" form="prefix">(</mo><mi>r</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi>r</mi><mn>2</mn></msup><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>ℒ</mi><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">b</mi><mi mathvariant="normal">s</mi></mrow></msub><mo stretchy="false" form="prefix">(</mo><mi>r</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">|</mo><mi>r</mi><mo stretchy="false" form="prefix">|</mo><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>ℒ</mi><mi>δ</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>r</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mo stretchy="true" form="prefix">{</mo><mtable><mtr><mtd columnalign="left" style="text-align: left"><mstyle displaystyle="false"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><msup><mi>r</mi><mn>2</mn></msup><mo>,</mo></mtd><mtd columnalign="left" style="text-align: left"><mo stretchy="false" form="prefix">|</mo><mi>r</mi><mo stretchy="false" form="prefix">|</mo><mo>≤</mo><mi>δ</mi><mo>,</mo></mtd></mtr><mtr><mtd columnalign="left" style="text-align: left"><mi>δ</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mo stretchy="false" form="prefix">|</mo><mi>r</mi><mo stretchy="false" form="prefix">|</mo><mi>−</mi><mstyle displaystyle="false"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mi>δ</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mo>,</mo></mtd><mtd columnalign="left" style="text-align: left"><mo stretchy="false" form="prefix">|</mo><mi>r</mi><mo stretchy="false" form="prefix">|</mo><mo>&gt;</mo><mi>δ</mi><mo>,</mo></mtd></mtr></mtable></mrow><mspace width="2.0em"></mspace><msub><mi>ℒ</mi><mi>q</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>r</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mo stretchy="true" form="prefix">{</mo><mtable><mtr><mtd columnalign="left" style="text-align: left"><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>q</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><mi>r</mi><mo>,</mo></mtd><mtd columnalign="left" style="text-align: left"><mi>r</mi><mo>≥</mo><mn>0</mn><mo>,</mo></mtd></mtr><mtr><mtd columnalign="left" style="text-align: left"><mi>−</mi><mi>q</mi><mspace width="0.167em"></mspace><mi>r</mi><mo>,</mo></mtd><mtd columnalign="left" style="text-align: left"><mi>r</mi><mo>&lt;</mo><mn>0</mn><mi>.</mi></mtd></mtr></mtable></mrow></mrow><annotation encoding="application/x-tex">\n\\mathcal L_{\\mathrm{sq}}(r) = r^2, \\qquad\n\\mathcal L_{\\mathrm{abs}}(r) = |r|, \\qquad\n\\mathcal L_{\\delta}(r) = \\begin{cases} \\tfrac12 r^2, &amp; |r| \\le \\delta,\\\\[2pt]\n\\delta\\bigl(|r| - \\tfrac12\\delta\\bigr), &amp; |r| &gt; \\delta,\\end{cases} \\qquad\n\\mathcal L_{q}(r) = \\begin{cases} (1-q)\\,r, &amp; r \\ge 0,\\\\ -q\\,r, &amp; r &lt; 0.\\end{cases}\n</annotation></semantics></math></p>\n<p>Последние две — потеря Хьюбера (квадратичная вблизи нуля, линейная на\nхвостах) и квантильная потеря (асимметричная: перепрогноз\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">r&gt;0</annotation></semantics></math>\nи недопрогноз\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi><mo>&lt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">r&lt;0</annotation></semantics></math>\nштрафуются с разными весами\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>−</mo><mi>q</mi></mrow><annotation encoding="application/x-tex">1-q</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>q</mi><annotation encoding="application/x-tex">q</annotation></semantics></math>).</p>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте четыре функции потерь от невязки r = a(x) - y</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_squared(r):</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_absolute(r):</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_huber(r, delta<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loss_quantile(r, q<span class="op">=</span><span class="fl">0.75</span>):</span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a>LOSSES <span class="op">=</span> {</span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;квадратичная&quot;</span>: loss_squared,</span>\n<span id="cb3-20"><a href="#cb3-20" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;абсолютная&quot;</span>: loss_absolute,</span>\n<span id="cb3-21"><a href="#cb3-21" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;Хьюбера&quot;</span>: loss_huber,</span>\n<span id="cb3-22"><a href="#cb3-22" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;квантильная (q=0.75)&quot;</span>: loss_quantile,</span>\n<span id="cb3-23"><a href="#cb3-23" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb3-24"><a href="#cb3-24" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-25"><a href="#cb3-25" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-26"><a href="#cb3-26" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> empirical_risk(loss, pred, y):</span>\n<span id="cb3-27"><a href="#cb3-27" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Q(a, X^l) -- среднее значение потерь по выборке.&quot;&quot;&quot;</span></span>\n<span id="cb3-28"><a href="#cb3-28" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-29"><a href="#cb3-29" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-30"><a href="#cb3-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-31"><a href="#cb3-31" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте графики всех четырёх потерь на одном рисунке</span></span>\n<span id="cb3-32"><a href="#cb3-32" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;ваш вариант:&quot;</span>, <span class="st">&quot;, &quot;</span>.join(variant[<span class="st">&quot;losses&quot;</span>]))</span></code></pre></div>\n</div>\n<div id="cell007" class="cell markdown">\n<h3 id="задание-12-оптимальный-константный-алгоритм">Задание 1.2.\nОптимальный константный алгоритм</h3>\n<p>Возьмём простейшую модель алгоритмов — константы:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>=</mo><mo stretchy="false" form="prefix">{</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>≡</mo><mi>c</mi><mo>∣</mo><mi>c</mi><mo>∈</mo><mi>ℝ</mi><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">A = \\{a(x) \\equiv c \\mid c \\in \\mathbb{R}\\}</annotation></semantics></math>.\nПринцип ERM (опр. 1.13) требует найти</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>c</mi><mo>*</mo></msup><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><munder><mi>min</mi><mi>c</mi></munder><mspace width="0.278em"></mspace><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></munderover><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>c</mi><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nc^* = \\arg\\min_{c} \\; \\frac1\\ell\\sum_{i=1}^{\\ell} \\mathcal L(c - y_i).\n</annotation></semantics></math></p>\n<p>Для каждой из ваших двух потерь найдите\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>c</mi><mo>*</mo></msup><annotation encoding="application/x-tex">c^*</annotation></semantics></math>\nчисленно (перебором по сетке или\n<code>scipy.optimize.minimize_scalar</code>) и сравните с выборочными\nхарактеристиками: средним, медианой и квантилями вектора\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>.\nПостройте график\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>c</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(c)</annotation></semantics></math>.</p>\n<p><strong>Это задание объясняет, почему в работе 1 константный ориентир\nдля MSE брался средним, а не медианой.</strong></p>\n</div>\n<div id="cell008" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>y_sample <span class="op">=</span> rng.gamma(shape<span class="op">=</span><span class="fl">2.0</span>, scale<span class="op">=</span><span class="fl">3.0</span>, size<span class="op">=</span><span class="dv">400</span>)     <span class="co"># заведомо несимметричное</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждой потери из variant[&quot;losses&quot;]:</span></span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) постройте график Q(c) на сетке значений c;</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) найдите c* численно (minimize_scalar с bounds или argmin по сетке);</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   3) сравните c* со средним, медианой и квантилью 0.75 вектора y_sample.</span></span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какой выборочной характеристике равен\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>c</mi><mo>*</mo></msup><annotation encoding="application/x-tex">c^*</annotation></semantics></math>\nдля каждой из ваших потерь? Почему для квадратичной потери это именно\nсреднее? (Продифференцируйте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>c</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(c)</annotation></semantics></math>\nпо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nи приравняйте нулю.)</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell010" class="cell markdown">\n<hr />\n<h1 id="часть-2-эмпирический-риск-против-истинного-проверяем-утверждение-112">Часть\n2. Эмпирический риск против истинного: проверяем утверждение 1.12</h1>\n<p>Утверждение 1.12 гласит: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>X</mi><mi>ℓ</mi></msup><annotation encoding="application/x-tex">X^\\ell</annotation></semantics></math>\n— простая выборка, то\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo><mo>=</mo><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathbb{E}\\bigl[Q(a, X^\\ell)\\bigr] = R(a)</annotation></semantics></math>.</p>\n<p>Ключевое слово — <strong>алгоритм\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>a</mi><annotation encoding="application/x-tex">a</annotation></semantics></math>\nфиксирован до того, как увидена выборка</strong>. В доказательстве\nиспользовано, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathcal L(a, x_i, y_i)</annotation></semantics></math>\nодинаково распределены; если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>a</mi><annotation encoding="application/x-tex">a</annotation></semantics></math>\nсам зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>X</mi><mi>ℓ</mi></msup><annotation encoding="application/x-tex">X^\\ell</annotation></semantics></math>,\nэто рассуждение рушится.</p>\n<p>Проверим оба случая на модели, где всё считается точно:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo>∼</mo><mi>U</mi><mo stretchy="false" form="prefix">[</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">]</mo><mo>,</mo><mspace width="2.0em"></mspace><mi>y</mi><mo>=</mo><msub><mi>θ</mi><mn>0</mn></msub><mo>+</mo><msub><mi>θ</mi><mn>1</mn></msub><mi>x</mi><mo>+</mo><mi>ε</mi><mo>,</mo><mspace width="2.0em"></mspace><mi>ε</mi><mo>∼</mo><mi>𝒩</mi><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nx \\sim U[0, 1], \\qquad y = \\theta_0 + \\theta_1 x + \\varepsilon,\n\\qquad \\varepsilon \\sim \\mathcal N(0, \\sigma^2).\n</annotation></semantics></math></p>\n<p>Для истинного алгоритма\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>a</mi><mo>*</mo></msup><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>θ</mi><mn>0</mn></msub><mo>+</mo><msub><mi>θ</mi><mn>1</mn></msub><mi>x</mi></mrow><annotation encoding="application/x-tex">a^*(x) = \\theta_0 + \\theta_1 x</annotation></semantics></math>\nистинный риск при квадратичной потере равен в точности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>𝔼</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mo>*</mo></msup><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo>=</mo><mi>𝔼</mi><msup><mi>ε</mi><mn>2</mn></msup><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R(a^*) = \\mathbb{E}(a^*(x) - y)^2 = \\mathbb{E}\\varepsilon^2 = \\sigma^2</annotation></semantics></math>.</p>\n</div>\n<div id="cell011" class="cell code">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>THETA_TRUE <span class="op">=</span> np.array([<span class="fl">2.0</span>, <span class="fl">3.0</span>])          <span class="co"># свободный член и наклон</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>SIGMA <span class="op">=</span> variant[<span class="st">&quot;noise_sigma&quot;</span>]             <span class="co"># из вашего варианта</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>ELL <span class="op">=</span> <span class="dv">30</span>                                   <span class="co"># размер обучающей выборки</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>N_REPEAT <span class="op">=</span> <span class="dv">3000</span>                            <span class="co"># число повторений эксперимента</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> sample(n, generator):</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Простая выборка (опр. 1.7) из описанного распределения p(x, y).&quot;&quot;&quot;</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>    x <span class="op">=</span> generator.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n)</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>    X <span class="op">=</span> np.column_stack([np.ones(n), x])</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>    y <span class="op">=</span> X <span class="op">@</span> THETA_TRUE <span class="op">+</span> generator.normal(<span class="dv">0</span>, SIGMA, n)</span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> X, y</span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;sigma = </span><span class="sc">{</span>SIGMA<span class="sc">}</span><span class="ss">, истинный риск R(a*) = sigma^2 = </span><span class="sc">{</span>SIGMA<span class="op">**</span><span class="dv">2</span><span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell012" class="cell markdown">\n<h3 id="задание-21-несмещённость-для-фиксированного-алгоритма">Задание\n2.1. Несмещённость для фиксированного алгоритма</h3>\n<p>Повторите\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>N</mi><annotation encoding="application/x-tex">N</annotation></semantics></math>\nраз: сгенерируйте выборку размера\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nи вычислите\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mo>*</mo></msup><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(a^*, X^\\ell)</annotation></semantics></math>\nдля <strong>истинного</strong> алгоритма. Постройте гистограмму\nполученных значений, отметьте на ней\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>σ</mi><mn>2</mn></msup><annotation encoding="application/x-tex">\\sigma^2</annotation></semantics></math>\nи среднее по повторениям.</p>\n</div>\n<div id="cell013" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: N_REPEAT раз сгенерируйте выборку размера ELL и посчитайте Q(a*, X^l)</span></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       для истинного алгоритма a*(x) = THETA_TRUE[0] + THETA_TRUE[1] * x.</span></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: гистограмма Q, вертикальные линии в sigma^2 и в среднем значении Q.</span></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: напечатайте относительное смещение и стандартное отклонение Q.</span></span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<h3 id="задание-22-что-происходит-если-алгоритм-выбран-по-той-же-выборке">Задание\n2.2. Что происходит, если алгоритм выбран по той же выборке</h3>\n<p>Теперь на каждой выборке решаем задачу ERM: подбираем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mover><mi>θ</mi><mo accent="true">̂</mo></mover><annotation encoding="application/x-tex">\\hat\\theta</annotation></semantics></math>\nметодом наименьших квадратов и считаем <strong>три</strong>\nвеличины:</p>\n<ul>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\hat a, X^\\ell)</annotation></semantics></math>\n— эмпирический риск на <strong>той же</strong> выборке (обучающая\nошибка);</li>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover><mi>R</mi><mo accent="true">̂</mo></mover><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\hat R(\\hat a)</annotation></semantics></math>\n— оценка истинного риска на большой независимой выборке;</li>\n<li><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>σ</mi><mn>2</mn></msup><annotation encoding="application/x-tex">\\sigma^2</annotation></semantics></math>\n— неустранимый уровень шума.</li>\n</ul>\n<p>Для линейной регрессии с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>\nпараметрами теория даёт точные ответы:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mspace width="0.167em"></mspace><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup><mo minsize="180%" maxsize="180%" stretchy="true" form="prefix">(</mo><mn>1</mn><mo>−</mo><mfrac><mi>p</mi><mi>ℓ</mi></mfrac><mo minsize="180%" maxsize="180%" stretchy="true" form="postfix">)</mo><mo>,</mo><mspace width="2.0em"></mspace><mi>𝔼</mi><mspace width="0.167em"></mspace><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo stretchy="false" form="postfix">)</mo><mo>≈</mo><msup><mi>σ</mi><mn>2</mn></msup><mo minsize="180%" maxsize="180%" stretchy="true" form="prefix">(</mo><mn>1</mn><mo>+</mo><mfrac><mi>p</mi><mi>ℓ</mi></mfrac><mo minsize="180%" maxsize="180%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathbb{E}\\,Q(\\hat a, X^\\ell) = \\sigma^2\\Bigl(1 - \\frac{p}{\\ell}\\Bigr),\n\\qquad\n\\mathbb{E}\\,R(\\hat a) \\approx \\sigma^2\\Bigl(1 + \\frac{p}{\\ell}\\Bigr).\n</annotation></semantics></math></p>\n<p>Проверьте обе формулы численно.</p>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE <span class="op">+</span> <span class="dv">1</span>)</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>X_big, y_big <span class="op">=</span> sample(<span class="dv">200_000</span>, gen)          <span class="co"># «генеральная совокупность» для оценки R</span></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: N_REPEAT раз:</span></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) сгенерируйте выборку размера ELL;</span></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) решите на ней задачу ERM (np.linalg.lstsq) -&gt; theta_hat;</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   3) посчитайте Q(a_hat) на этой же выборке и R(a_hat) на большой выборке.</span></span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравните средние с теоретическими sigma^2 (1 -+ p/l), p = 2.</span></span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте две гистограммы на одном рисунке.</span></span></code></pre></div>\n</div>\n<div id="cell016" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему для фиксированного алгоритма смещения\nнет, а для обученного — есть? В каком месте доказательства утверждения\n1.12 ломается рассуждение? Как зазор\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo>−</mo><mi>Q</mi></mrow><annotation encoding="application/x-tex">R - Q</annotation></semantics></math>\nзависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nи от числа параметров\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell017" class="cell markdown">\n<hr />\n<h1 id="часть-3-матричное-дифференцирование-проверка-формул">Часть 3.\nМатричное дифференцирование: проверка формул</h1>\n<p>В §6 лекции 1 выведены два тождества:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>w</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mi>𝖳</mi></msup><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>a</mi><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>∇</mi><mi>w</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><mi>A</mi><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo>+</mo><msup><mi>A</mi><mi>𝖳</mi></msup><mo stretchy="false" form="postfix">)</mo><mi>w</mi><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\nabla_w (a^{\\mathsf T} w) = a,\n\\qquad\n\\nabla_w (w^{\\mathsf T} A w) = (A + A^{\\mathsf T}) w,\n</annotation></semantics></math></p>\n<p>и из них — градиент квадрата нормы невязки:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>θ</mi></msub><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\nabla_\\theta \\|X\\theta - y\\|^2 = 2 X^{\\mathsf T}(X\\theta - y).\n</annotation></semantics></math></p>\n<p>Проверим их <strong>численно</strong>: сравним аналитический градиент\nс центральной конечной разностью</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mi>∂</mi><mi>f</mi></mrow><mrow><mi>∂</mi><msub><mi>w</mi><mi>k</mi></msub></mrow></mfrac><mo>≈</mo><mfrac><mrow><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo>+</mo><mi>h</mi><msub><mi>e</mi><mi>k</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo>−</mo><mi>h</mi><msub><mi>e</mi><mi>k</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><mrow><mn>2</mn><mi>h</mi></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\frac{\\partial f}{\\partial w_k} \\approx\n\\frac{f(w + h e_k) - f(w - h e_k)}{2h}.\n</annotation></semantics></math></p>\n<p>Приём стоит запомнить: при реализации любого градиента «с нуля»\n(работы 3, 4) эта проверка за пять строк ловит ошибку в выкладке.</p>\n</div>\n<div id="cell018" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> numeric_grad(f, w, h<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиент центральными разностями.&quot;&quot;&quot;</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте покоординатную центральную разность</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">6</span></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>w0 <span class="op">=</span> rng.normal(size<span class="op">=</span>n)</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>a <span class="op">=</span> rng.normal(size<span class="op">=</span>n)</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>A <span class="op">=</span> rng.normal(size<span class="op">=</span>(n, n))                       <span class="co"># намеренно несимметричная</span></span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: проверьте три формулы, сравнив аналитический градиент с численным:</span></span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = a^T w             -&gt; grad = a</span></span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = w^T A w           -&gt; grad = (A + A^T) w</span></span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = ||X w - y||^2     -&gt; grad = 2 X^T (X w - y)</span></span></code></pre></div>\n</div>\n<div id="cell019" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему в формуле\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>w</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><mi>A</mi><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo>+</mo><msup><mi>A</mi><mi>𝖳</mi></msup><mo stretchy="false" form="postfix">)</mo><mi>w</mi></mrow><annotation encoding="application/x-tex">\\nabla_w(w^{\\mathsf T}Aw) = (A + A^{\\mathsf T})w</annotation></semantics></math>\nважна несимметричность\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>?\nЧто будет с точностью численного градиента при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>h</mi><mo>=</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>12</mn></mrow></msup></mrow><annotation encoding="application/x-tex">h = 10^{-12}</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell020" class="cell markdown">\n<hr />\n<h1 id="часть-4-мнк-нормальные-уравнения-и-svd">Часть 4. МНК: нормальные\nуравнения и SVD</h1>\n<p>Теорема 1.20: если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nневырождена, то</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\theta^* = (X^{\\mathsf T}X)^{-1} X^{\\mathsf T} y.\n</annotation></semantics></math></p>\n<p>Формулу с обратной матрицей <strong>никогда не реализуют\nбуквально</strong>. Сравним пять способов решить одну и ту же\nзадачу:</p>\n<ol>\n<li><code>np.linalg.inv(X.T @ X) @ X.T @ y</code> — прямое обращение\n(так делать не надо);</li>\n<li><code>np.linalg.solve(X.T @ X, X.T @ y)</code> — разложение\nХолецкого нормальных уравнений;</li>\n<li>QR-разложение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>Q</mi><mi>R</mi></mrow><annotation encoding="application/x-tex">X = QR</annotation></semantics></math>,\nзатем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mi>θ</mi><mo>=</mo><msup><mi>Q</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">R\\theta = Q^{\\mathsf T}y</annotation></semantics></math>;</li>\n<li><code>np.linalg.lstsq</code> — SVD-решение (то же, что\nпсевдообратная матрица);</li>\n<li>SVD вручную:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>U</mi><mi mathvariant="normal">Σ</mi><msup><mi>V</mi><mi>𝖳</mi></msup><mo>⇒</mo><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mi>V</mi><msup><mi mathvariant="normal">Σ</mi><mo>+</mo></msup><msup><mi>U</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">X = U\\Sigma V^{\\mathsf T} \\Rightarrow \\theta^* = V\\Sigma^{+}U^{\\mathsf T}y</annotation></semantics></math>.</li>\n</ol>\n<p>Ваш вариант требует реализовать два из них (см.\n<code>variant[&quot;solver_pair&quot;]</code>), но полезно написать все.</p>\n</div>\n<div id="cell021" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> linalg</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_inv(X, y):</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;(X^T X)^{-1} X^T y -- буквально по формуле теоремы 1.20.&quot;&quot;&quot;</span></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_solve(X, y):</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Решение нормальных уравнений X^T X theta = X^T y без обращения.&quot;&quot;&quot;</span></span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-14"><a href="#cb9-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_qr(X, y):</span>\n<span id="cb9-15"><a href="#cb9-15" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;X = QR, R theta = Q^T y.&quot;&quot;&quot;</span></span>\n<span id="cb9-16"><a href="#cb9-16" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-17"><a href="#cb9-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-18"><a href="#cb9-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-19"><a href="#cb9-19" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_lstsq(X, y):</span>\n<span id="cb9-20"><a href="#cb9-20" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;SVD-решение средствами numpy.&quot;&quot;&quot;</span></span>\n<span id="cb9-21"><a href="#cb9-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-22"><a href="#cb9-22" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-23"><a href="#cb9-23" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-24"><a href="#cb9-24" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_svd(X, y, tol<span class="op">=</span><span class="fl">1e-12</span>):</span>\n<span id="cb9-25"><a href="#cb9-25" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;SVD вручную: theta = V Sigma^+ U^T y.&quot;&quot;&quot;</span></span>\n<span id="cb9-26"><a href="#cb9-26" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-27"><a href="#cb9-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-28"><a href="#cb9-28" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-29"><a href="#cb9-29" aria-hidden="true" tabindex="-1"></a>SOLVERS <span class="op">=</span> {</span>\n<span id="cb9-30"><a href="#cb9-30" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;нормальные уравнения через обращение (np.linalg.inv)&quot;</span>: fit_inv,</span>\n<span id="cb9-31"><a href="#cb9-31" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;нормальные уравнения (np.linalg.solve)&quot;</span>: fit_solve,</span>\n<span id="cb9-32"><a href="#cb9-32" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;QR-разложение (scipy.linalg.qr)&quot;</span>: fit_qr,</span>\n<span id="cb9-33"><a href="#cb9-33" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;SVD (np.linalg.lstsq)&quot;</span>: fit_lstsq,</span>\n<span id="cb9-34"><a href="#cb9-34" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;SVD (np.linalg.svd вручную)&quot;</span>: fit_svd,</span>\n<span id="cb9-35"><a href="#cb9-35" aria-hidden="true" tabindex="-1"></a>}</span>\n<span id="cb9-36"><a href="#cb9-36" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;ваш вариант:&quot;</span>, <span class="st">&quot; | &quot;</span>.join(variant[<span class="st">&quot;solver_pair&quot;</span>]))</span></code></pre></div>\n</div>\n<div id="cell022" class="cell markdown">\n<h3 id="задание-41-сверка-с-примером-из-лекции">Задание 4.1. Сверка с\nпримером из лекции</h3>\n<p>В примере 1.21 лекции 1 МНК применён к выборке из восьми кошек:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>f</mi><mn>1</mn></msub><annotation encoding="application/x-tex">f_1</annotation></semantics></math>\n— число банок корма в день,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>f</mi><mn>2</mn></msub><annotation encoding="application/x-tex">f_2</annotation></semantics></math>\n— возраст,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\n— вес. Лекция даёт\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>≈</mo><mo stretchy="false" form="prefix">(</mo><mn>2.201</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.893</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.114</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^* \\approx (2.201,\\ 0.893,\\ 0.114)</annotation></semantics></math>.</p>\n<p>Воспроизведите этот результат всеми пятью способами.</p>\n</div>\n<div id="cell023" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Данные примера 1.5 лекции 1</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a>f1 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">1</span>, <span class="dv">4</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a>f2 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">5</span>, <span class="dv">7</span>, <span class="dv">10</span>, <span class="dv">2</span>, <span class="dv">8</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a>y_cats <span class="op">=</span> np.array([<span class="fl">3.0</span>, <span class="fl">4.2</span>, <span class="fl">4.5</span>, <span class="fl">5.5</span>, <span class="fl">4.8</span>, <span class="fl">6.0</span>, <span class="fl">3.4</span>, <span class="fl">6.6</span>])</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: соберите матрицу X_cats со столбцом единиц, примените все пять решателей,</span></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       сравните с theta* = (2.201, 0.893, 0.114) из примера 1.21 лекции.</span></span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: выведите cond(X^T X) и cond(X).</span></span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<h3 id="задание-42-когда-нормальные-уравнения-ломаются">Задание 4.2.\nКогда нормальные уравнения ломаются</h3>\n<p>Число обусловленности связано соотношением\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X^{\\mathsf T}X) = \\mathrm{cond}(X)^2</annotation></semantics></math>:\nпереход к нормальным уравнениям <strong>возводит обусловленность в\nквадрат</strong>, то есть теряет вдвое больше верных знаков.</p>\n<p>Проверьте это на матрице Вандермонда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>X</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><msubsup><mi>t</mi><mi>i</mi><mrow><mspace width="0.167em"></mspace><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msubsup></mrow><annotation encoding="application/x-tex">X_{ij} = t_i^{\\,j-1}</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>j</mi><mo>=</mo><mn>1</mn><mo>,</mo><mi>…</mi><mo>,</mo><mi>p</mi></mrow><annotation encoding="application/x-tex">j = 1,\\dots,p</annotation></semantics></math>\n— она печально известна своей обусловленностью. Постройте график ошибки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mover><mi>θ</mi><mo accent="true">̂</mo></mover><mo>−</mo><msub><mi>θ</mi><mtext mathvariant="normal">истина</mtext></msub><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\hat\\theta - \\theta_{\\text{истина}}\\|</annotation></semantics></math>\nдля всех пяти методов в зависимости от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>\n(число столбцов) в логарифмическом масштабе.</p>\n</div>\n<div id="cell025" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>t <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">120</span>)</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>degrees <span class="op">=</span> <span class="bu">range</span>(<span class="dv">2</span>, <span class="dv">15</span>)</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждого p:</span></span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) X_v = np.vander(t, p, increasing=True), theta_true случайный, y_v = X_v @ theta_true;</span></span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) решите задачу всеми пятью методами и запомните ||theta_hat - theta_true||;</span></span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   3) запомните cond(X_v).</span></span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: два графика в логарифмическом масштабе: ошибка методов и cond(X), cond(X)^2.</span></span></code></pre></div>\n</div>\n<div id="cell026" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Начиная с какого\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>\nметод с явным обращением даёт бессмысленный ответ? Как это связано с\nмашинной точностью\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi><mo>≈</mo><mn>2</mn><mo>⋅</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>16</mn></mrow></msup></mrow><annotation encoding="application/x-tex">\\varepsilon \\approx 2\\cdot10^{-16}</annotation></semantics></math>\nи с равенством\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X^{\\mathsf T}X) = \\mathrm{cond}(X)^2</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell027" class="cell markdown">\n<hr />\n<h1 id="часть-5-максимум-правдоподобия-и-выбор-функции-потерь">Часть 5.\nМаксимум правдоподобия и выбор функции потерь</h1>\n<p>Утверждение 1.15 связывает ERM и ММП: если положить\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>θ</mi></msub><mo>,</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathcal L(a_\\theta, x, y) = -\\ln\\varphi(x, y, \\theta)</annotation></semantics></math>,\nто принципы совпадают. Для линейной модели с гауссовским шумом (пример\n1.22)</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo>=</mo><mi>C</mi><mo>+</mo><mfrac><mn>1</mn><mrow><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup></mrow></mfrac><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mn>2</mn></msup><mspace width="0.278em"></mspace><mo>⇒</mo><mspace width="0.278em"></mspace><msub><mi>θ</mi><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">L</mi></mrow></msub><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><munder><mi>min</mi><mi>θ</mi></munder><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><msubsup><mi>θ</mi><mrow><mi mathvariant="normal">М</mi><mi mathvariant="normal">Н</mi><mi mathvariant="normal">К</mi></mrow><mo>*</mo></msubsup><mi>.</mi></mrow><annotation encoding="application/x-tex">\n-\\ln\\varphi = C + \\frac{1}{2\\sigma^2}\\bigl(g(x,\\theta) - y\\bigr)^2\n\\;\\Longrightarrow\\;\n\\theta_{\\mathrm{ML}} = \\arg\\min_\\theta \\|X\\theta - y\\|^2 = \\theta^*_{\\mathrm{МНК}} .\n</annotation></semantics></math></p>\n<p>А если шум лапласовский,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>ε</mi><mo stretchy="false" form="postfix">)</mo><mo>∝</mo><msup><mi>e</mi><mrow><mi>−</mi><mo stretchy="false" form="prefix">|</mo><mi>ε</mi><mo stretchy="false" form="prefix">|</mo><mi>/</mi><mi>b</mi></mrow></msup></mrow><annotation encoding="application/x-tex">p(\\varepsilon) \\propto e^{-|\\varepsilon| / b}</annotation></semantics></math>,\nто\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo>=</mo><mi>C</mi><mo>+</mo><mo stretchy="false" form="prefix">|</mo><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi><mo stretchy="false" form="prefix">|</mo><mi>/</mi><mi>b</mi></mrow><annotation encoding="application/x-tex">-\\ln\\varphi = C + |g(x,\\theta) - y| / b</annotation></semantics></math>,\nи ММП приводит к <strong>абсолютной</strong> потере, то есть к медианной\nрегрессии.</p>\n<p>Проверим оба утверждения численно и посмотрим, что происходит при\nвыбросах.</p>\n</div>\n<div id="cell028" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> neg_loglik_gauss(theta, X, y, sigma<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;-ln L(theta) для модели y = X theta + N(0, sigma^2).&quot;&quot;&quot;</span></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> neg_loglik_laplace(theta, X, y, b<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;-ln L(theta) для модели y = X theta + Laplace(0, b).&quot;&quot;&quot;</span></span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">120</span></span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a>x <span class="op">=</span> np.sort(rng.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n))</span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a>X_lin <span class="op">=</span> np.column_stack([np.ones(n), x])</span>\n<span id="cb12-14"><a href="#cb12-14" aria-hidden="true" tabindex="-1"></a>y_clean <span class="op">=</span> X_lin <span class="op">@</span> THETA_TRUE <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.3</span>, n)</span>\n<span id="cb12-15"><a href="#cb12-15" aria-hidden="true" tabindex="-1"></a>y_dirty <span class="op">=</span> y_clean.copy()</span>\n<span id="cb12-16"><a href="#cb12-16" aria-hidden="true" tabindex="-1"></a>outlier_idx <span class="op">=</span> rng.choice(n, size<span class="op">=</span><span class="dv">6</span>, replace<span class="op">=</span><span class="va">False</span>)</span>\n<span id="cb12-17"><a href="#cb12-17" aria-hidden="true" tabindex="-1"></a>y_dirty[outlier_idx] <span class="op">+=</span> rng.choice([<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>], <span class="dv">6</span>) <span class="op">*</span> rng.uniform(<span class="dv">6</span>, <span class="dv">12</span>, <span class="dv">6</span>)</span>\n<span id="cb12-18"><a href="#cb12-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-19"><a href="#cb12-19" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) для y_clean и для y_dirty найдите theta тремя способами:</span></span>\n<span id="cb12-20"><a href="#cb12-20" aria-hidden="true" tabindex="-1"></a><span class="co">#          МНК (fit_lstsq), минимизацией neg_loglik_gauss, минимизацией neg_loglik_laplace</span></span>\n<span id="cb12-21"><a href="#cb12-21" aria-hidden="true" tabindex="-1"></a><span class="co">#          (для лапласовской используйте method=&quot;Nelder-Mead&quot; -- функция негладкая);</span></span>\n<span id="cb12-22"><a href="#cb12-22" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сведите результаты в таблицу и сравните с THETA_TRUE;</span></span>\n<span id="cb12-23"><a href="#cb12-23" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) на диаграмме рассеяния покажите обе прямые и истинную зависимость.</span></span></code></pre></div>\n</div>\n<div id="cell029" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли ММП при гауссовском шуме и МНК?\nКакая из двух прямых устояла против выбросов и почему? Как это связано с\nчастью 1 работы?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell030" class="cell markdown">\n<hr />\n<h1 id="часть-6-полиномиальная-регрессия-первое-переобучение">Часть 6.\nПолиномиальная регрессия: первое переобучение</h1>\n<p>Как отмечено в примере 1.4 лекции 1, признаками линейной модели могут\nбыть любые функции исходных данных: при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msup><mi>x</mi><mrow><mspace width="0.167em"></mspace><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msup></mrow><annotation encoding="application/x-tex">f_j(x) = x^{\\,j-1}</annotation></semantics></math>\nта же формула\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>θ</mi><mi>j</mi></msub><msub><mi>f</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">g(x,\\theta) = \\sum_j \\theta_j f_j(x)</annotation></semantics></math>\nзадаёт полином степени\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n - 1</annotation></semantics></math>.\nМодель остаётся <strong>линейной по параметрам</strong>, поэтому весь\nаппарат МНК применим без изменений.</p>\n<p>Постройте полиномы степеней из вашего варианта, обучив их своей\nреализацией МНК, и сравните эмпирический риск на обучающей и на\nконтрольной выборке.</p>\n</div>\n<div id="cell031" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> poly_design(x, degree):</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Матрица объектов-признаков для полинома: столбцы 1, x, x^2, ..., x^degree.&quot;&quot;&quot;</span></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a>n_train, n_test <span class="op">=</span> <span class="dv">30</span>, <span class="dv">500</span></span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a>x_tr <span class="op">=</span> np.sort(rng.uniform(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>, n_train))</span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a>x_te <span class="op">=</span> np.sort(rng.uniform(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>, n_test))</span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a>true_f <span class="op">=</span> <span class="kw">lambda</span> t: np.sin(<span class="dv">3</span> <span class="op">*</span> t) <span class="op">+</span> <span class="fl">0.5</span> <span class="op">*</span> t</span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a>y_tr <span class="op">=</span> true_f(x_tr) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, n_train)</span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a>y_te <span class="op">=</span> true_f(x_te) <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, n_test)</span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждой степени из variant[&quot;poly_degrees&quot;]:</span></span>\n<span id="cb13-14"><a href="#cb13-14" aria-hidden="true" tabindex="-1"></a><span class="co">#   обучите полином своей реализацией МНК, посчитайте Q на обучающей и контрольной</span></span>\n<span id="cb13-15"><a href="#cb13-15" aria-hidden="true" tabindex="-1"></a><span class="co">#   выборках, запомните max|theta_j|.</span></span>\n<span id="cb13-16"><a href="#cb13-16" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: два графика: (а) данные и подогнанные полиномы; (б) Q(степень) для обеих</span></span>\n<span id="cb13-17"><a href="#cb13-17" aria-hidden="true" tabindex="-1"></a><span class="co">#       выборок в логарифмическом масштабе по оси Q.</span></span></code></pre></div>\n</div>\n<div id="cell032" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как ведут себя обучающая и контрольная ошибки\nс ростом степени? Что происходит с величиной коэффициентов\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mrow><mi>max</mi><mo>⁡</mo></mrow><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">\\max_j |\\theta_j|</annotation></semantics></math>?\nКакая степень оптимальна и можно ли было выбрать её по обучающей\nошибке?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell033" class="cell markdown">\n<hr />\n<h1 id="часть-7-своя-выборка">Часть 7. Своя выборка</h1>\n<p>Примените свою реализацию МНК к индивидуальной выборке,\nподготовленной в работе 1. Функция <code>load_personal</code> повторяет\nэталонную предобработку из первой работы (приведение типов, чистка\nкатегорий, удаление дубликатов, вырожденных признаков и <code>id</code>,\nразбиение и кодирование), чтобы результаты не зависели от аккуратности\nвашего кода в работе 1.</p>\n<p>Для задачи классификации МНК применяется к индикатору класса, а ответ\nберётся по порогу\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>0.5</mn><annotation encoding="application/x-tex">0.5</annotation></semantics></math>;\nэто законная, но не лучшая конструкция — корректный подход\n(логистическая регрессия) будет на лекции 3.</p>\n</div>\n<div id="cell034" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>Xtr, Xte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a>ytr, yte <span class="op">=</span> data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;</span><span class="sc">{</span>data[<span class="st">&#39;domain&#39;</span>]<span class="sc">}</span><span class="ss">: </span><span class="sc">{</span>data[<span class="st">&#39;task&#39;</span>]<span class="sc">}</span><span class="ss">, обучающая </span><span class="sc">{</span>Xtr<span class="sc">.</span>shape<span class="sc">}</span><span class="ss">, контрольная </span><span class="sc">{</span>Xte<span class="sc">.</span>shape<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) добавьте столбец единиц и обучите свою реализацию МНК;</span></span>\n<span id="cb14-9"><a href="#cb14-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сверьте со sklearn.linear_model.LinearRegression ОТДЕЛЬНО предсказания</span></span>\n<span id="cb14-10"><a href="#cb14-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          и коэффициенты; заодно выведите np.linalg.matrix_rank(Atr) и число</span></span>\n<span id="cb14-11"><a href="#cb14-11" aria-hidden="true" tabindex="-1"></a><span class="co">#          столбцов Atr -- расхождение объяснится само;</span></span>\n<span id="cb14-12"><a href="#cb14-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) сравните Q на обучающей и контрольной выборке с константным ориентиром,</span></span>\n<span id="cb14-13"><a href="#cb14-13" aria-hidden="true" tabindex="-1"></a><span class="co">#          посчитайте R^2 на контроле;</span></span>\n<span id="cb14-14"><a href="#cb14-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) если задача классификационная -- посчитайте долю правильных ответов</span></span>\n<span id="cb14-15"><a href="#cb14-15" aria-hidden="true" tabindex="-1"></a><span class="co">#          при пороге 0.5 и долю предсказаний, вышедших за отрезок [0, 1].</span></span></code></pre></div>\n</div>\n<div id="cell035" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Предсказания вашей реализации и\n<code>sklearn</code> совпали, а коэффициенты — нет. Сравните ранг\nматрицы с числом её столбцов и объясните, почему так вышло и почему\nтеорема 1.20 здесь неприменима.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell036" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Насколько МНК лучше константы на вашей\nвыборке? Если у вас задача классификации — какая доля предсказаний вышла\nза отрезок\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">[0,1]</annotation></semantics></math>\nи почему это плохо?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell037" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Утверждение 1.12 говорит, что\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo stretchy="false" form="prefix">[</mo><mi>Q</mi><mo stretchy="false" form="postfix">]</mo><mo>=</mo><mi>R</mi></mrow><annotation encoding="application/x-tex">\\mathbb{E}[Q] = R</annotation></semantics></math>.\nПочему это не противоречит переобучению? Сформулируйте условие, при\nкотором равенство верно.</li>\n<li>Вы получили\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mover><mi>a</mi><mo accent="true">̂</mo></mover><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">Q(\\hat a, X^\\ell) = 0</annotation></semantics></math>.\nЧто это говорит о качестве алгоритма на новых объектах? Приведите пример\nалгоритма с нулевым эмпирическим риском и максимально плохим\nистинным.</li>\n<li>Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">\\theta^* = (X^{\\mathsf T}X)^{-1}X^{\\mathsf T}y</annotation></semantics></math>\n— правильная формула, но неправильная реализация?</li>\n<li>Как связаны выбор функции потерь и предположение о распределении\nшума? Какой потере соответствует шум Лапласа и какую характеристику\nусловного распределения\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\nона восстанавливает?</li>\n<li>Модель полиномов степени\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≤</mo><mi>d</mi></mrow><annotation encoding="application/x-tex">\\le d</annotation></semantics></math>\nвложена в модель степени\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≤</mo><mi>d</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\le d+1</annotation></semantics></math>.\nДокажите, что минимум эмпирического риска по большей модели не больше,\nчем по меньшей. Почему из этого <strong>не</strong> следует, что большая\nмодель лучше?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>Взвешенный МНК.</strong> Пусть объекты имеют веса\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>w</mi><mi>i</mi></msub><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">w_i &gt; 0</annotation></semantics></math>\nи минимизируется\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mo>∑</mo><mi>i</mi></msub><msub><mi>w</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mo stretchy="false" form="prefix">⟨</mo><mi>θ</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">⟩</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\sum_i w_i (\\langle \\theta, x_i\\rangle - y_i)^2</annotation></semantics></math>.\nВыведите нормальные уравнения (через матричное дифференцирование, как в\n§6 лекции 1) и покажите, что решение равно\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>W</mi><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>W</mi><mi>y</mi></mrow><annotation encoding="application/x-tex">\\theta^* = (X^{\\mathsf T}WX)^{-1}X^{\\mathsf T}Wy</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>W</mi><mo>=</mo><mrow><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">g</mi></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>w</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">W = \\mathrm{diag}(w_i)</annotation></semantics></math>.\nРеализуйте и проверьте: (а) совпадение со <code>sklearn</code> при\n<code>sample_weight</code>; (б) что при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>w</mi><mi>i</mi></msub><mo>=</mo><mn>1</mn><mi>/</mi><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">w_i = 1/\\sigma_i^2</annotation></semantics></math>\nи гетероскедастичном шуме\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>ε</mi><mi>i</mi></msub><mo>∼</mo><mi>𝒩</mi><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\varepsilon_i \\sim \\mathcal N(0, \\sigma_i^2)</annotation></semantics></math>\nвзвешенный МНК точнее обычного (сравните по 500 повторениям).</p></li>\n<li><p><strong>Свой <code>numeric_grad</code> для матричного\nаргумента.</strong> Обобщите проверку градиента на функции матричного\nаргумента\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>W</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">f(W)</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>W</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>m</mi><mo>×</mo><mi>n</mi></mrow></msup></mrow><annotation encoding="application/x-tex">W \\in \\mathbb{R}^{m\\times n}</annotation></semantics></math>,\nи проверьте формулы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>W</mi></msub><mrow><mi mathvariant="normal">t</mi><mi mathvariant="normal">r</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>A</mi><mi>𝖳</mi></msup><mi>W</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">\\nabla_W \\mathrm{tr}(A^{\\mathsf T}W) = A</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>W</mi></msub><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>W</mi><mo>−</mo><mi>Y</mi><msubsup><mo stretchy="false" form="postfix">∥</mo><mi>F</mi><mn>2</mn></msubsup><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>W</mi><mo>−</mo><mi>Y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla_W \\|XW - Y\\|_F^2 = 2X^{\\mathsf T}(XW - Y)</annotation></semantics></math>.\nВторая формула — это многомерная линейная регрессия (несколько целевых\nпеременных сразу); проверьте, что она сводится к независимому решению\nзадач по столбцам\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Y</mi><annotation encoding="application/x-tex">Y</annotation></semantics></math>.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);